const suggestRecipes = (ingredients, recipes) => {
  const available = new Set(ingredients.map((item) => item.name));
  return recipes
    .map((recipe) => ({
      ...recipe,
      match: recipe.ingredients.filter((name) => available.has(name)).length
    }))
    .sort((a, b) => b.match - a.match);
};

type StockItem = {
  name: string;
  expiresAt: Date;
  quantity: number;
};

const prioritizeStock = (items: StockItem[]) =>
  items
    .filter((item) => item.quantity > 0)
    .sort((a, b) => a.expiresAt.getTime() - b.expiresAt.getTime());

const compareImpact = (recipe, alternative) => ({
  difference: recipe.impact - alternative.impact,
  reduction: Math.round(
    ((recipe.impact - alternative.impact) / recipe.impact) * 100
  )
});

const groupNotesByProject = (notes) =>
  notes.reduce((groups, note) => {
    const project = note.projectId;
    groups[project] ??= [];
    groups[project].push(note);
    return groups;
  }, {});

